//! 🫧️ Energy's authored empty ephemeral lanes retain their actual registries and typed disposers through native instance admission.
use semio_framework_os_kernel as store;
use semio_framework_plugin_decl_views::{NoPresence,NoPresenceMutation,NoTransient,NoTransientMutation,presence_retirement};
use semio_framework_plugin_ownership::{store_lifecycle::ArtifactOwnedDisposer,transient_publication};
use semio_framework_job::*;
use semio_framework_value::{RetirementDemand,RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep,ValueError,ValueRefusalKind,FactoryAuthority,FactoryRetirement};
use semio_framework_value_snapshot_read::snapshot_read_registry_handle::birth::SnapshotReadRegistryBirth;
use std::{mem::{size_of,size_of_val,ManuallyDrop},sync::Arc};
type Presence=store::PresenceStore<NoPresence,NoPresenceMutation>;
type Transient=store::TransientStore<NoTransient,NoTransientMutation>;
type Disposer<T>=Box<dyn ArtifactOwnedDisposer<T>>;
fn invalid(message:&'static str)->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,message)}
fn fixed<T>()->RetirementDemand{RetirementDemand{copy_bytes:2*size_of::<T>(),depth:1,..Default::default()}}
fn construction(d:RetirementDemand)->OriginalConstructionDemand{OriginalConstructionDemand{items:1,copy_bytes:d.copy_bytes,capacity_bytes:d.capacity_bytes,release_bytes:d.release_bytes,depth:d.depth}}
/// 🧳️ These exact roots and original disposers move into the mounted instance; no second empty Store is built.
pub struct OriginalEmptyEphemeralStores{binding:OriginalSourceBinding,presence:ManuallyDrop<Option<Presence>>,transient:ManuallyDrop<Option<Transient>>,presence_disposer:ManuallyDrop<Option<Disposer<Presence>>>,transient_disposer:ManuallyDrop<Option<Disposer<Transient>>>,presence_factory:ManuallyDrop<Option<Arc<dyn store::SnapshotRetirementFactory<NoPresence>>>>,transient_factory:ManuallyDrop<Option<Arc<dyn store::SnapshotRetirementFactory<NoTransient>>>>,factory_close:[Option<FactoryAuthority>;2],closing:bool}
impl OriginalEmptyEphemeralStores{
 fn empty(binding:OriginalSourceBinding)->Self{Self{binding,presence:ManuallyDrop::new(None),transient:ManuallyDrop::new(None),presence_disposer:ManuallyDrop::new(None),transient_disposer:ManuallyDrop::new(None),presence_factory:ManuallyDrop::new(None),transient_factory:ManuallyDrop::new(None),factory_close:[None,None],closing:false}}
 pub fn presence(&self)->&Presence{self.presence.as_ref().expect("native empty presence source is ready")}
 pub fn transient(&self)->&Transient{self.transient.as_ref().expect("native empty transient source is ready")}
 pub fn into_parts(mut self)->(Presence,Transient,Disposer<Presence>,Disposer<Transient>,Arc<dyn store::SnapshotRetirementFactory<NoPresence>>,Arc<dyn store::SnapshotRetirementFactory<NoTransient>>){let value=(self.presence.take().unwrap(),self.transient.take().unwrap(),self.presence_disposer.take().unwrap(),self.transient_disposer.take().unwrap(),self.presence_factory.take().unwrap(),self.transient_factory.take().unwrap());self.closing=true;value}
 pub fn close_step(&mut self,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{if !self.binding.matches(cx){return Err(invalid("ephemeral closure changed its original caller").into())}self.closing=true;if !close_store(&mut self.presence,&mut self.presence_disposer,cx)?||!close_store(&mut self.transient,&mut self.transient_disposer,cx)?{return Ok(false)}if self.presence_factory.is_some(){let d=fixed::<(Option<Arc<dyn FactoryRetirement>>,Option<FactoryAuthority>)>();close_original_retained_step(cx,d,|_|{let original:Arc<dyn FactoryRetirement>=self.presence_factory.take().unwrap();self.factory_close[0]=Some(FactoryAuthority::new(original));Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))})?;return Ok(false)}if self.transient_factory.is_some(){let d=fixed::<(Option<Arc<dyn FactoryRetirement>>,Option<FactoryAuthority>)>();close_original_retained_step(cx,d,|_|{let original:Arc<dyn FactoryRetirement>=self.transient_factory.take().unwrap();self.factory_close[1]=Some(FactoryAuthority::new(original));Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))})?;return Ok(false)}for index in 0..2{if let Some(owner)=self.factory_close[index].as_mut(){if owner.terminal_is_empty(){let d=fixed::<Option<FactoryAuthority>>();close_original_retained_step(cx,d,|_|{self.factory_close[index]=None;Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))})?;}else{let d=owner.demands(4096)?;close_original_retained_step(cx,d,|g|owner.step(g))?;}return Ok(false)}}Ok(self.terminal_is_empty())}
 pub fn terminal_is_empty(&self)->bool{self.closing&&self.presence.is_none()&&self.transient.is_none()&&self.presence_disposer.is_none()&&self.transient_disposer.is_none()&&self.presence_factory.is_none()&&self.transient_factory.is_none()&&self.factory_close.iter().all(Option::is_none)}
}
impl Drop for OriginalEmptyEphemeralStores{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"original ephemeral payloads retain their actual typed closure until transfer or retirement")}}
fn close_store<T>(store:&mut Option<T>,disposer:&mut Option<Disposer<T>>,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{let Some(owner)=store.as_ref()else{if disposer.is_some(){return Err(invalid("native ephemeral disposer lost its original Store").into())}return Ok(true)};let closer=disposer.as_ref().ok_or_else(||invalid("native ephemeral Store lost its defining disposer"))?;if closer.terminal_is_empty(owner){let bytes=closer.terminal_frame_release_bytes().filter(|bytes|*bytes==size_of_val(closer.as_ref())).ok_or_else(||invalid("native ephemeral terminal frame retains original payload"))?;let d=RetirementDemand{release_bytes:bytes,..fixed::<(Option<T>,Option<Disposer<T>>)>()};close_original_retained_step(cx,d,|_|{store.take();disposer.take();Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,released_bytes:d.release_bytes,..Default::default()}))})?;}else{let d=closer.retirement_demands(owner,4096)?;close_original_retained_turn(cx,d,|g|{let step=disposer.as_mut().unwrap().close_step(store.as_mut().unwrap(),g).map_err(OriginalTurnPrimary::Fault)?;Ok(RetainedCloneStep::Progress(step.progress().unwrap_or_default()))})?;}Ok(false)}
/// 🌱️ Each original registry page is admitted before its corresponding concrete empty Store birth.
pub struct OriginalEmptyEphemeralSource{binding:OriginalSourceBinding,owned:ManuallyDrop<Option<OriginalEmptyEphemeralStores>>,presence_birth:ManuallyDrop<SnapshotReadRegistryBirth>,transient_birth:ManuallyDrop<SnapshotReadRegistryBirth>,phase:u8,closing:bool}
impl OriginalEmptyEphemeralSource{
 pub fn birth_demands()->RetirementDemand{RetirementDemand{capacity_bytes:size_of::<Self>(),..fixed::<Self>()}}
 pub fn admit(cx:&mut StepContext<'_>,output:&mut Option<Box<Self>>)->Result<bool,OriginalTurnFailure>{if output.is_some(){return Err(invalid("empty ephemeral source recipient is occupied").into())}let d=Self::birth_demands();let binding=OriginalSourceBinding::borrow(cx);admit_original_construction(cx,output,construction(d),|_|Ok((Box::new(Self{binding,owned:ManuallyDrop::new(Some(OriginalEmptyEphemeralStores::empty(binding))),presence_birth:ManuallyDrop::new(SnapshotReadRegistryBirth::new()),transient_birth:ManuallyDrop::new(SnapshotReadRegistryBirth::new()),phase:0,closing:false}),RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,retained_capacity_bytes:d.capacity_bytes,..Default::default()})))?;Ok(output.is_some())}
 pub fn progress(&self)->u8{self.phase}
 pub fn ready(&self)->bool{self.phase==4&&!self.closing}
 pub fn advance(&mut self,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{if !self.binding.matches(cx)||self.closing{return Err(invalid("empty ephemeral source changed caller or lifecycle").into())}if cx.is_cancelled()||cx.should_yield(){return Ok(false)}match self.phase{
 0=>{if self.presence_birth.ready()?{self.phase=1;}else{advance_registry(&mut self.presence_birth,cx)?;}},
 1=>{let mut d=Presence::original_birth_demands();d.copy_bytes+=size_of::<store::SnapshotReadRegistryHandle>()+2*size_of::<Disposer<Presence>>()+size_of::<Arc<dyn store::SnapshotRetirementFactory<NoPresence>>>();d.capacity_bytes+=semio_framework_value::shared_retirement_allocation_bytes::<NoPresence>()+semio_framework_value::shared_retirement_allocation_bytes::<presence_retirement::NoPresenceRetirementFactory>()+size_of::<presence_retirement::PresenceStoreOwnedDisposer<NoPresence>>();let g=cx.retained_grant();let mut done=None;admit_original_construction(cx,&mut done,construction(d),|_|{let(reads,_)=self.presence_birth.take(g)?.ok_or_else(||invalid("original presence registry is not ready"))?;let mut local=Some(NoPresence{});let mut reads=Some(reads);let(mut store,_)=Presence::admit_original(&mut local,&mut reads,g)?.ok_or_else(||invalid("original presence Store admission refused its funded quote"))?;let factory=presence_retirement::no_presence_local_root_retirement_factory();store.install_local_retirement_factory(factory.clone()).map_err(|_|invalid("native presence local issuer was already installed"))?;store.install_peer_retirement_factory(factory.clone()).map_err(|_|invalid("native presence peer issuer was already installed"))?;let owned=self.owned.as_mut().unwrap();*owned.presence=Some(store);*owned.presence_factory=Some(factory);*owned.presence_disposer=Some(presence_retirement::no_presence_store_disposer());self.phase=2;Ok(((),RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,retained_capacity_bytes:d.capacity_bytes,..Default::default()}))})?;},
 2=>{if self.transient_birth.ready()?{self.phase=3;}else{advance_registry(&mut self.transient_birth,cx)?;}},
 3=>{let mut d=Transient::original_birth_demands();d.copy_bytes+=size_of::<store::SnapshotReadRegistryHandle>()+2*size_of::<Disposer<Transient>>()+size_of::<Arc<dyn store::SnapshotRetirementFactory<NoTransient>>>();d.capacity_bytes+=semio_framework_value::shared_retirement_allocation_bytes::<semio_framework_value_factory::OwnedValueRetirementFactory<NoTransient>>()+semio_framework_value::shared_retirement_allocation_bytes::<semio_framework_value_factory::SharedValueRetirementFactory<NoTransient>>()+size_of::<transient_publication::TransientStoreDisposer<NoTransient,NoTransientMutation>>();let g=cx.retained_grant();let mut done=None;admit_original_construction(cx,&mut done,construction(d),|_|{let(reads,_)=self.transient_birth.take(g)?.ok_or_else(||invalid("original transient registry is not ready"))?;let mut initial=Some(NoTransient{});let mut reads=Some(reads);let(store,_)=Transient::admit_original(&mut initial,&mut reads,g)?.ok_or_else(||invalid("original transient Store admission refused its funded quote"))?;let owned=self.owned.as_mut().unwrap();*owned.transient=Some(store);*owned.transient_factory=Some(transient_publication::bounded_transient_root_retirement_factory::<NoTransient>());*owned.transient_disposer=Some(transient_publication::bounded_transient_store_disposer::<NoTransient,NoTransientMutation>());self.phase=4;Ok(((),RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,retained_capacity_bytes:d.capacity_bytes,..Default::default()}))})?;},_=>{}}
 Ok(self.ready())}
 pub fn take(&mut self,cx:&mut StepContext<'_>,output:&mut Option<OriginalEmptyEphemeralStores>)->Result<bool,OriginalTurnFailure>{if !self.binding.matches(cx)||!self.ready()||output.is_some(){return Err(invalid("empty ephemeral source handoff requires its unchanged ready recipient").into())}let d=fixed::<OriginalEmptyEphemeralStores>();admit_original_construction(cx,output,construction(d),|_|{self.closing=true;Ok((self.owned.take().unwrap(),RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))})?;Ok(output.is_some())}
 pub fn close_step(&mut self,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{if !self.binding.matches(cx){return Err(invalid("empty ephemeral close changed original caller").into())}self.closing=true;if let Some(owned)=self.owned.as_mut(){if !owned.close_step(cx)?{return Ok(false)}let d=fixed::<Option<OriginalEmptyEphemeralStores>>();close_original_retained_step(cx,d,|_|{self.owned.take();Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))})?;return Ok(false)}for birth in [&mut*self.presence_birth,&mut*self.transient_birth]{birth.begin_close();if !birth.terminal_is_empty(){let d=birth.close_demands()?;let g=cx.retained_grant();if !semio_framework_value::retained_clone::retained_clone_grant_admits(g,d){return Ok(false)}let result=cx.with_native_retirement(|control|birth.close_step(g,control));let p=result.as_ref().map(|s|s.progress()).unwrap_or_else(|e|e.retained_progress());cx.consume_retained(p)?;cx.consume_fuel(p.copied_items as u64);result?;return Ok(false)}}Ok(self.terminal_is_empty())}
 pub fn terminal_is_empty(&self)->bool{self.closing&&self.owned.is_none()&&self.presence_birth.terminal_is_empty()&&self.transient_birth.terminal_is_empty()}
 pub fn boxed_release_demands()->RetirementDemand{RetirementDemand{release_bytes:size_of::<Self>(),..fixed::<Option<Box<Self>>>()}}
}
impl Drop for OriginalEmptyEphemeralSource{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"native ephemeral source retains every original registry page until handoff or paid cancellation")}}
fn advance_registry(birth:&mut SnapshotReadRegistryBirth,cx:&mut StepContext<'_>)->Result<(),OriginalTurnFailure>{let d=birth.demands()?;let g=cx.retained_grant();if !semio_framework_value::retained_clone::retained_clone_grant_admits(g,d){return Ok(())}let result=cx.with_native_receiving(|control|birth.advance(g,control));let p=result.as_ref().map(|s|s.progress()).unwrap_or_else(|e|e.retained_progress());let reconciled=cx.receiving_issued_grant().ok_or_else(||invalid("native registry birth omitted its original receiving scope")).and_then(|issued|cx.consume_receiving_retained(issued,p));cx.consume_fuel(p.copied_items as u64);match(result,reconciled){(Ok(_),Ok(()))=>Ok(()),(Err(error),Ok(()))=>Err(error.into()),(Ok(_),Err(error))=>Err(error.into()),(Err(error),Err(receipt))=>{let mut failure=OriginalTurnFailure::from(error);failure.context_refusal=Some(receipt);Err(failure)}}}

